mapper.select:
SELECT id FROM notification_outbox
 WHERE status = 'PENDING'
   AND tenant_id = #{tenantId}
   AND next_attempt_at <= #{now}
 ORDER BY next_attempt_at ASC
 LIMIT #{batchSize}
 FOR UPDATE SKIP LOCKED

SELECT id FROM notification_outbox
 WHERE status = 'PENDING'
   AND tenant_id = #{tenantId}
   AND next_attempt_at <= #{now}
 ORDER BY next_attempt_at ASC
 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE notification_outbox
   SET status = 'SENDING', claimed_at = #{claimedAt}, claimed_by = #{instanceId}
 WHERE id IN #{i}

UPDATE notification_outbox
   SET status = 'SENT', sent_at = #{sentAt}, last_error = #{externalMessageId,jdbcType=VARCHAR}
 WHERE id = #{id}

UPDATE notification_outbox
   SET status = 'PERMANENT_FAILURE', permanent_failure_reason = #{reason,jdbcType=VARCHAR},
       last_error = #{error,jdbcType=VARCHAR}, last_error_at = #{errorAt}
 WHERE id = #{id}

UPDATE notification_outbox
   SET status = 'PENDING', claimed_at = NULL, claimed_by = NULL
 WHERE status = 'SENDING' AND claimed_at < #{cutoff}

mapper.select:
SELECT  FROM notification_outbox
 WHERE correlation_id = #{correlationId,jdbcType=OTHER}
 ORDER BY channel_type ASC

SELECT  FROM notification_outbox
 WHERE status = 'PENDING' AND created_at < #{olderThan}
 ORDER BY created_at ASC
